  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "空气被抽干"
        },
        {
          "id": "B1-02",
          "zh": "干瘪的我啊"
        },
        {
          "id": "B1-03",
          "zh": "呜呼已是你的所有物"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "空气被抽干 我"
        },
        {
          "id": "B1-02",
          "zh": "瘪下去的我 啊"
        },
        {
          "id": "B1-03",
          "zh": "呜呼 已是你的 所有物"
        }
      ]
    },
    {
      "label": "C",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "空气被抽干后"
        },
        {
          "id": "B1-02",
          "zh": "干瘪的我啊"
        },
        {
          "id": "B1-03",
          "zh": "啊已是你的所有物"
        }
      ]
    },
    {
      "label": "D",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "气被抽走 慢慢变空"
        },
        {
          "id": "B1-02",
          "zh": "瘪掉的我 皱在掌心"
        },
        {
          "id": "B1-03",
          "zh": "也罢 我已是 你所有"
        }
      ]
    },
    {
      "label": "E",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "气被抽干 只剩皱褶"
        },
        {
          "id": "B1-02",
          "zh": "塌成一只 旧的气球"
        },
        {
          "id": "B1-03",
          "zh": "原是 你指间 的旧物"
        }
      ]
    },
    {
      "label": "F",
      "phrases": [
        {
          "id": "B1-01",
          "zh": "被抽空了空气"
        },
        {
          "id": "B1-02",
          "zh": "我干瘪着枯萎"
        },
        {
          "id": "B1-03",
          "zh": "呜呼 已成你的所有物"
        }
      ]
    }
  ]
}

